package org.sleepwell.app;
import android.os.SystemClock;import android.util.*;import android.view.*;import androidx.activity.ComponentActivity;import androidx.camera.core.*;import androidx.camera.core.resolutionselector.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import androidx.camera.mlkit.vision.MlKitAnalyzer;import androidx.core.content.ContextCompat;import androidx.lifecycle.Lifecycle;import com.google.common.util.concurrent.ListenableFuture;import com.google.mlkit.vision.face.*;import java.util.*;import java.util.concurrent.*;
/** Visible front-camera analysis through CameraX MlKitAnalyzer. Only numeric observations leave it. */
final class SmileCamera implements AutoCloseable {
 interface Listener{void frame(SmileHold.Sample sample,String issue);void error(String issue);}
 static final class Meta{final int width,height;final long at;Meta(int w,int h,long at){width=w;height=h;this.at=at;}}
 final ComponentActivity activity;final PreviewView view;final Map<Long,Meta> frames=new ConcurrentHashMap<>();ProcessCameraProvider provider;Preview preview;ImageAnalysis analysis;Camera camera;FaceDetector detector;ExecutorService worker;volatile boolean active;volatile long generation;
 SmileCamera(ComponentActivity a){activity=a;view=new PreviewView(a);view.setImplementationMode(PreviewView.ImplementationMode.COMPATIBLE);view.setScaleType(PreviewView.ScaleType.FIT_CENTER);}
 View preview(){return view;}
 void start(Listener listener){close();long ticket=++generation;active=true;worker=Executors.newSingleThreadExecutor();detector=FaceDetection.getClient(new FaceDetectorOptions.Builder().setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_FAST).setClassificationMode(FaceDetectorOptions.CLASSIFICATION_MODE_ALL).setMinFaceSize(.15f).build());FaceDetector owned=detector;ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(activity);future.addListener(()->{if(!live(ticket)||!activity.getLifecycle().getCurrentState().isAtLeast(Lifecycle.State.RESUMED))return;try{if(SmileCameraAccess.status(activity)!=SmileCameraAccess.Status.READY)throw new SecurityException();provider=future.get();if(!provider.hasCamera(CameraSelector.DEFAULT_FRONT_CAMERA))throw new IllegalStateException();preview=new Preview.Builder().build();preview.setSurfaceProvider(view.getSurfaceProvider());analysis=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).setResolutionSelector(new ResolutionSelector.Builder().setAspectRatioStrategy(AspectRatioStrategy.RATIO_4_3_FALLBACK_AUTO_STRATEGY).setResolutionStrategy(new ResolutionStrategy(new Size(640,480),ResolutionStrategy.FALLBACK_RULE_CLOSEST_LOWER_THEN_HIGHER)).build()).build();MlKitAnalyzer analyzer=new MlKitAnalyzer(List.of(owned),ImageAnalysis.COORDINATE_SYSTEM_ORIGINAL,ContextCompat.getMainExecutor(activity),result->{Meta meta=frames.remove(result.getTimestamp());if(!live(ticket)||meta==null)return;if(result.getThrowable(owned)!=null){listener.frame(null,"Smile detector unavailable. Retry or use Math.");return;}List<Face> faces=result.getValue(owned);if(faces==null||faces.size()!=1){listener.frame(null,faces==null||faces.isEmpty()?"Face the front camera in good light.":"Keep just one face in view.");return;}Face face=faces.get(0);android.graphics.Rect box=face.getBoundingBox();Float probability=face.getSmilingProbability();if(probability==null||box.width()<100||box.height()<100){listener.frame(null,"Move closer and face the camera so your smile is visible.");return;}SmileHold.Sample sample=new SmileHold.Sample(box.left/(double)meta.width,box.top/(double)meta.height,box.right/(double)meta.width,box.bottom/(double)meta.height,probability,face.getHeadEulerAngleY(),face.getHeadEulerAngleX(),face.getHeadEulerAngleZ(),meta.at);listener.frame(sample,!sample.framed()?probability<.80?"Smile naturally and hold it steady.":"Center your face and look straight at the camera.":"");});long[] last={-1,-1};analysis.setAnalyzer(worker,image->{boolean delegated=false;try{if(!live(ticket))return;long now=SystemClock.elapsedRealtime(),sensor=image.getImageInfo().getTimestamp();if(last[0]>=0&&now-last[0]<200||sensor<=last[1])return;last[0]=now;last[1]=sensor;long captured=PictureHold.captured(sensor,now,System.nanoTime()/1000000L);if(captured<0){activity.runOnUiThread(()->{if(live(ticket))listener.frame(null,"Camera timing is unavailable. Retry or use Math.");});return;}int rotation=image.getImageInfo().getRotationDegrees();int w=rotation==90||rotation==270?image.getHeight():image.getWidth(),h=rotation==90||rotation==270?image.getWidth():image.getHeight();if(w<360||h<360)throw new IllegalArgumentException();if(frames.size()>3)frames.clear();frames.put(sensor,new Meta(w,h,captured));analyzer.analyze(image);delegated=true;}catch(RuntimeException unavailable){activity.runOnUiThread(()->{if(live(ticket))listener.frame(null,"This camera frame could not be analyzed. Retry or use Math.");});}finally{if(!delegated)image.close();}});int rotation=view.getDisplay()==null?Surface.ROTATION_0:view.getDisplay().getRotation();UseCaseGroup group=new UseCaseGroup.Builder().setViewPort(new ViewPort.Builder(new Rational(4,3),rotation).setScaleType(ViewPort.FIT).build()).addUseCase(preview).addUseCase(analysis).build();camera=provider.bindToLifecycle(activity,CameraSelector.DEFAULT_FRONT_CAMERA,group);camera.getCameraInfo().getCameraState().observe(activity,state->{if(live(ticket)&&state.getError()!=null)listener.error("Front camera is unavailable or in use. Retry or use Math.");});}catch(Exception unavailable){if(live(ticket))listener.error(unavailable instanceof SecurityException?"Camera access is off.":"The front camera or smile detector could not start. Use Math or retry.");}},ContextCompat.getMainExecutor(activity));}
 boolean live(long ticket){return active&&generation==ticket&&!activity.isDestroyed();}
 @Override public void close(){active=false;generation++;frames.clear();if(analysis!=null)analysis.clearAnalyzer();if(camera!=null)camera.getCameraInfo().getCameraState().removeObservers(activity);try{if(provider!=null){if(preview!=null&&analysis!=null)provider.unbind(preview,analysis);else if(preview!=null)provider.unbind(preview);else if(analysis!=null)provider.unbind(analysis);}}finally{preview=null;analysis=null;camera=null;if(detector!=null){detector.close();detector=null;}if(worker!=null){worker.shutdown();worker=null;}}}
}
